using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Use the web-defaults options (has metadata for common types via reflection).
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// ── 1. Strongly-typed metadata retrieval ──────────────────────────
// GetTypeInfo<T>() returns JsonTypeInfo<T> directly — no casting needed.
JsonTypeInfo<int[]> arrayMeta = options.GetTypeInfo<int[]>();
Console.WriteLine($"Typed metadata for int[]: Kind = {arrayMeta.Kind}");

// ── 2. Probe without throwing ─────────────────────────────────────
// TryGetTypeInfo returns false instead of throwing when the type isn't
// resolvable (e.g. when using a source-gen context that doesn't include it).
if (options.TryGetTypeInfo(typeof(string), out JsonTypeInfo? stringMeta))
    Console.WriteLine($"string metadata found:  Kind = {stringMeta!.Kind}");
else
    Console.WriteLine("string metadata NOT available");

// Demonstrate a "not-found" branch with a source-gen context that only
// knows about one type.
var limited = new JsonSerializerOptions { TypeInfoResolver = new LimitedContext() };

if (limited.TryGetTypeInfo(typeof(int), out _))
    Console.WriteLine("int metadata found in limited context");
else
    Console.WriteLine("int metadata NOT available in limited context  ✓");

// ── Minimal custom resolver that resolves nothing ─────────────────
class LimitedContext : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

